import assert from 'node:assert/strict';
import { spawn, execFileSync } from 'node:child_process';
import { mkdtemp, mkdir, writeFile, readFile, open } from 'node:fs/promises';
import path from 'node:path';
import { NectarService } from '../../dist/service.js';
import { serveEntries, serveStatus } from '../../dist/tailscale.js';
import { pidAlive } from '../../dist/commands.js';
import { daemonHello, callDaemon } from '../../dist/control.js';
const root = path.resolve(process.argv[2] ?? `.audit/recovery-${Date.now()}`);
await mkdir(root, {recursive:true});
const repo = path.join(root,'fixture');
await mkdir(repo);
const git = (...args) => execFileSync('git',args,{cwd:repo,stdio:'pipe'});
git('init','-b','main'); git('config','user.email','fixture@example.invalid'); git('config','user.name','Fixture');
await writeFile(path.join(repo,'nectar.toml'),'name = "recovery"\n[web]\nserve = "exec node server.mjs"\nready_timeout = "5s"\n');
await writeFile(path.join(repo,'server.mjs'),'import http from "node:http"; http.createServer((req,res)=>{res.writeHead(200);res.write("awake:"+process.env.NECTAR_ENV);if(req.url!=="/stream")res.end();}).listen(Number(process.env.PORT),"127.0.0.1");');
git('add','.'); git('commit','-m','Fixture');
const state = path.join(root,'state');
process.env.NECTAR_HOME=state; process.env.NECTAR_SOCKET=path.join(await mkdtemp('/tmp/nectar-t5-'),'control.sock');
process.env.NECTAR_TEST_RUNTIME_MEMORY_BYTES=String(12*256*1024**2);
const service = new NectarService(state);
await service.store.init();
await service.store.writeConfig({...await service.store.readConfig(),upstream_port_start:33100,upstream_port_end:33123,tailnet_port_start:33400,tailnet_port_end:33500,pack_server_port:33099,idle_stop_ms:3600000});
const log=await open(path.join(root,'daemon.log'),'a');
const daemon=spawn(process.execPath,['dist/cli.js','daemon','run','--interval','1s','--gc-interval','1h'],{env:process.env,stdio:['ignore',log.fd,log.fd]});
const wait=ms=>new Promise(r=>setTimeout(r,ms));
const until=async fn=>{const end=Date.now()+20000;while(!await fn()){assert(Date.now()<end,'timeout');await wait(100);}};
const say=x=>console.log(JSON.stringify(x));
const records=[];
const startedPids=new Set();
const curl=url=>{const value=execFileSync('curl',['-sS','--max-time','20',url],{encoding:'utf8'});assert(value.startsWith('awake:'),value);return value;};
try {
 await until(async()=>{try{return (await daemonHello(process.env.NECTAR_SOCKET)).pid===daemon.pid;}catch{return false;}});
 say({isolatedDaemon:daemon.pid,state});
 for(let i=1;i<=12;i++) {
  const branch=`p${String(i).padStart(2,'0')}`;git('branch',branch);
  const result=await callDaemon(process.env.NECTAR_SOCKET,'publish',{nectar_home:state,caller:{},args:{path:repo,branch,mode:'web',local:true}}); assert.equal(result.via,'nectard');
  const record=await service.store.readEnv(result.env);records.push(record);
  assert(curl(result.preview_url).includes(record.name));
  assert.equal((await service.store.readEnv(record.name)).urls.mesh,record.urls.mesh);
  say({publish:i,url:result.preview_url,status:200});
 }
 for(const r of await service.store.listEnvs())if(r.serve?.pid>1)startedPids.add(r.serve.pid);
 await service.store.updateEnv(records[0].name,r=>{r.pinned=true;});
 const controller=new AbortController();
 const stream=await fetch(records[1].urls.local+'/stream',{signal:controller.signal});
 assert.equal(stream.status,200);
 git('branch','p13');
 const envelope={ok:true,result:await callDaemon(process.env.NECTAR_SOCKET,'publish',{nectar_home:state,caller:{},args:{path:repo,branch:'p13',mode:'web',local:true}})};
 assert.deepEqual(envelope.result.slept_previews,[records[2].name]);
 assert.equal((await service.store.readEnv(records[2].name)).status,'warm');
 say({thirteenthPublish:envelope});
 await service.store.writeConfig({...await service.store.readConfig(),upstream_port_end:33299});
 assert(curl(envelope.result.preview_url).includes(envelope.result.env));
 const woke=execFileSync('curl',['-isS','--max-time','20',records[2].urls.mesh ?? records[2].urls.local],{encoding:'utf8'});
 assert(woke.includes(records[2].name));
 assert.match(woke,/x-nectar-slept-previews: recovery--p04--web/i);
 assert.equal((await service.store.readEnv(records[2].name)).urls.mesh,records[2].urls.mesh);
 say({wakeResponse:woke});
 say({sleptUrlWakes:records[2].urls.mesh ?? records[2].urls.local,status:200,capacityEvents:await readFile(path.join(state,'capacity.jsonl'),'utf8')});
 assert.equal((await service.store.readEnv(records[0].name)).status,'serving');
 assert.equal((await service.store.readEnv(records[1].name)).status,'serving');
 controller.abort();
 for(const record of await service.store.listEnvs())await service.store.updateEnv(record.name,r=>{r.pinned=true;});
 await service.store.writeConfig({...await service.store.readConfig(),upstream_port_end:33123});
 git('branch','p14');
 let refused;try{await callDaemon(process.env.NECTAR_SOCKET,'publish',{nectar_home:state,caller:{},args:{path:repo,branch:'p14',mode:'web',local:true}});}catch(error){refused={ok:false,error:{code:error.code,message:error.message}};}
 assert.equal(refused.ok,false); assert.match(refused.error.message,/[Cc]onfigure nectar pool add/); assert(!refused.error.message.includes('slot'));
 say({noEligibleRuntime:refused});
} finally {
 const finalRecords=await service.store.listEnvs();
 for(const r of finalRecords)if(r.serve?.pid>1)startedPids.add(r.serve.pid);
 for(const record of finalRecords)await service.stop(record.name).catch(()=>{});
 daemon.kill('SIGTERM');await new Promise(resolve=>daemon.once('exit',resolve));await log.close();
 const remaining=serveEntries(await serveStatus()).filter(e=>finalRecords.some(r=>r.serve?.tailnet_port===e.tailnetPort));
 assert.deepEqual(remaining,[]);
 assert([...startedPids].every(pid=>!pidAlive(pid)));
 say({cleanup:'own previews stopped; own daemon exited',remainingRoutes:remaining,startedPidsGone:startedPids.size,root});
}
